{
  "lines": [
    {
      "text": "Wer Pein hat, sieht Schmerz"
    },
    {
      "text": "sein letztes Ende kommen"
    },
    {
      "text": "die Hoffnung, die ihn tröste"
    },
    {
      "text": "soll, ist ihm gewiß benommen"
    },
    {
      "text": "der liebe Gott, nur dieser"
    },
    {
      "text": "hilft, und auf dem Tode"
    },
    {
      "text": "folgt das Gericht"
    },
    {
      "text": "Gerd H. Peters"
    },
    {
      "text": "Suurhusen"
    }
  ],
  "script": "kurrent",
  "notes": "Poesiealbum entry with floral illustration. Handwriting is Kurrent."
}

